import os
from sqlalchemy import text

class SensorDataFetcher:
    def get_latest_sensor_reading(self, session):
        sensor_id = os.getenv("SENSOR_ID")
        query = "SELECT * FROM readings WHERE sensor_id = '%s' ORDER BY timestamp DESC LIMIT 1" % sensor_id
        return session.execute(text(query)).fetchone()

