import psycopg2
import logging

def filter_books_by_author_year(cursor, author=None, year=None):
    query = "SELECT * FROM books WHERE 1=1"
    params = []

    if author is not None:
        if not isinstance(author, str):
            raise TypeError("Author must be a string")
        author = author.strip()
        if not author:
            author = None

    if year is not None:
        try:
            year = int(year)
        except (TypeError, ValueError):
            logging.warning("Invalid publication year")
            return []
        if year < 0:
            logging.warning("Publication year cannot be negative")
            return []

    if author:
        query += " AND author = %s"
        params.append(author)
    if year:
        query += " AND publication_year = %s"
        params.append(year)

    try:
        cursor.execute(query, params)
        return cursor.fetchall()
    except psycopg2.Error as e:
        logging.error(f"Database error: {e}")
        return None

def get_books_by_author_year(cursor, author=None, year=None):
    return filter_books_by_author_year(cursor, author, year)

import csv
import io
from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/format_orders', methods=['POST'])
def format_orders():
    data = request.json
    if not isinstance(data, list):
        return Response("Invalid input", status=400)

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(['Order ID', 'Customer Name', 'Product', 'Quantity', 'Price'])

    for record in data:
        if all(key in record for key in ['order_id', 'customer_name', 'product', 'quantity', 'price']):
            writer.writerow([
                record['order_id'],
                record['customer_name'],
                record['product'],
                record['quantity'],
                record['price']
            ])

    return Response(output.getvalue(), mimetype='text/csv')

if __name__ == '__main__':
    app.run(debug=False)
